397:     {
398:       rr = libraw_internal_data.internal_output_params.fuji_width - 1 - col +
399:            (row >> 1);
400:       cc = col + ((row + 1) >> 1);
401:     }
402:     else
403:     {
404:       rr = libraw_internal_data.internal_output_params.fuji_width - 1 + row -
405:            (col >> 1);
406:       cc = row + ((col + 1) >> 1);
407:     }
408:     return FC(rr, cc);
