774: INT64 LibRaw_bigfile_buffered_datastream::readAt(void *ptr, size_t size, INT64 off)
775: {
776:     LR_BF_CHK();
777:     DWORD NumberOfBytesRead;
778:     DWORD nNumberOfBytesToRead = (DWORD)size;
779:     struct _OVERLAPPED olap;
780:     memset(&olap, 0, sizeof(olap));
781:     olap.Offset = off & 0xffffffff;
782:     olap.OffsetHigh = off >> 32;
783: 	if (ReadFile(fhandle, ptr, nNumberOfBytesToRead, &NumberOfBytesRead, &olap))
784: 		return NumberOfBytesRead;
785: 	else if (NumberOfBytesRead > 0)
786: 		return NumberOfBytesRead;
787: 	else
788:         return 0;
789: }
