791: #define MAX(a, b) ((a) > (b) ? (a) : (b))
792: #define MIN(a, b) ((a) < (b) ? (a) : (b))
793: 
794: #ifdef _MSC_VER
795: #pragma intrinsic(memcpy)
796: #endif
