798: int LibRaw_bigfile_buffered_datastream::read(void *data, size_t size, size_t nmemb)
799: {
800:     if (size < 1 || nmemb < 1)
801:         return 0;
802:     LR_BF_CHK();
803:     INT64 count = size * nmemb;
804:     INT64 partbytes = 0;
805:     if (!buffered)
806:     {
807:         INT64 r = readAt(data, count, _fpos);
808:         _fpos += r;
809:         return int(r / size);
810:     }
811: 
812:     unsigned char *fBuffer = (unsigned char*)iobuffers[0].data();
813:     while (count)
814:     {
815:         INT64 inbuffer = 0;
816:         // See if the request is totally inside buffer.
817:         if (iobuffers[0].contains(_fpos, inbuffer))
818:         {
819:             if (inbuffer >= count)
820:             {
821:                 memcpy(data, fBuffer + (unsigned)(_fpos - iobuffers[0]._bstart), count);
822:                 _fpos += count;
823:                 return int((count + partbytes) / size);
824:             }
825:             memcpy(data, fBuffer + (_fpos - iobuffers[0]._bstart), inbuffer);
826:             partbytes += inbuffer;
827:             count -= inbuffer;
828:             data = (void *)(((char *)data) + inbuffer);
829:             _fpos += inbuffer;
830:         }
831:         if (count > (INT64) iobuffers[0].size())
832:         {
833:         fallback:
834:             if (_fpos + count > _fsize)
835:                 count = MAX(0, _fsize - _fpos);
836:             if (count > 0)
837:             {
838:                 INT64 r = readAt(data, count, _fpos);
839:                 _fpos += r;
840:                 return int((r + partbytes) / size);
841:             }
842:             else
843:                 return 0;
844:         }
845: 
846:         if (!fillBufferAt(0, _fpos))
847:             goto fallback;
848:     }
849:     return 0;
850: }
