852: bool LibRaw_bigfile_buffered_datastream::fillBufferAt(int bi, INT64 off)
853: {
854:     if (off < 0LL) return false;
855:     iobuffers[bi]._bstart = off;
856:     if (iobuffers[bi].size() >= LIBRAW_BUFFER_ALIGN * 2)// Align to a file block.
857:         iobuffers[bi]._bstart &= (INT64)~((INT64)(LIBRAW_BUFFER_ALIGN - 1));
858: 
859:     iobuffers[bi]._bend = MIN(iobuffers[bi]._bstart + (INT64)iobuffers[bi].size(), _fsize);
860:     if (iobuffers[bi]._bend <= off) // Buffer alignment problem, fallback
861:         return false;
862:     INT64 rr = readAt(iobuffers[bi].data(), (uint32_t)(iobuffers[bi]._bend - iobuffers[bi]._bstart), iobuffers[bi]._bstart);
863:     if (rr > 0)
864:     {
865:         iobuffers[bi]._bend = iobuffers[bi]._bstart + rr;
866:         return true;
867:     }
868:     return false;
869: }
