893: char *LibRaw_bigfile_buffered_datastream::gets(char *s, int sz)
894: {
895:     if (sz < 1)
896:         return NULL;
897:     else if (sz < 2)
898:     {
899:         s[0] = 0;
900:         return s;
901:     }
902: 
903:     LR_BF_CHK();
904:     INT64 contains;
905:     int bufindex = selectStringBuffer(sz, contains);
906:     if (bufindex < 0) return NULL;
907:     if (contains >= sz)
908:     {
909:         unsigned char *buf = iobuffers[bufindex].data() + (_fpos - iobuffers[bufindex]._bstart);
910:         INT64 streampos = 0;
911:         INT64 streamsize = contains;
912:         unsigned char *str = (unsigned char *)s;
913:         unsigned char *psrc, *pdest;
914:         psrc = buf + streampos;
915:         pdest = str;
916: 
917:         while ((INT64(psrc - buf) < streamsize) && ((pdest - str) < INT64(sz)-1)) // sz-1: to append \0
918:         {
919:             *pdest = *psrc;
920:             if (*psrc == '\n')
921:                 break;
922:             psrc++;
923:             pdest++;
924:         }
925:         if (INT64(psrc - buf) < streamsize)
926:             psrc++;
927:         if ((pdest - str) < sz - 1)
928:             *(++pdest) = 0;
929:         else
930:             s[sz - 1] = 0; // ensure trailing zero
931:         streampos = psrc - buf;
932:         _fpos += streampos;
933:         return s;
934:     }
935:     return NULL;
936: }
